package com.servicedesk360.controller;
import com.servicedesk360.dto.common.PageResponse; import com.servicedesk360.dto.notification.NotificationResponse; import com.servicedesk360.service.NotificationService; import org.springframework.data.domain.Pageable; import org.springframework.data.web.PageableDefault; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/notifications") public class NotificationController{private final NotificationService service;public NotificationController(NotificationService s){service=s;}@GetMapping public PageResponse<NotificationResponse> list(@PageableDefault(size=20,sort="createdAt",direction=org.springframework.data.domain.Sort.Direction.DESC)Pageable p){return service.list(p);}@GetMapping("/unread-count") public long unreadCount(){return service.unreadCount();}@PatchMapping("/{id}/read") public NotificationResponse markRead(@PathVariable Long id){return service.markRead(id);}}
